def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    urgent_opp_count = 0
    rich_aggro_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            urgent_opp_count += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) >= 90 and opp.get('budget', 0) >= 500:
                rich_aggro_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = int(supply // WATER_REQ)
    scarce = units <= 1
    medium_tight = units == 2

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 1
    if scarce:
        danger += 2
    elif medium_tight:
        danger += 1
    if urgent_opp_count >= 2:
        danger += 1

    if danger >= 6:
        target = max(92.0, highest_prev + 3.0)
    elif danger >= 4:
        target = max(72.0, avg_prev + 2.0)
    elif danger >= 2:
        if rich_aggro_count >= 1 and highest_prev >= 95:
            target = 34.0
        else:
            target = max(48.0, min(78.0, highest_prev * 0.72 + 2.0))
    else:
        if rich_aggro_count >= 1 or highest_prev >= 100:
            target = 22.0
        elif highest_prev >= 80:
            target = 28.0
        else:
            target = 36.0

    if day >= 8 and (hp <= 4 or no_water >= 1):
        target += 8.0
    if day >= 9 and hp <= 3:
        target += 10.0

    reserve_floor = 0.0
    if day < 8:
        reserve_floor = DAILY_SALARY * (10 - day) * 0.18
    max_affordable = max(0.0, budget - reserve_floor)
    if max_affordable <= 0:
        max_affordable = budget

    bid = min(target, budget, max_affordable)

    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(budget, 88.0))
    elif scarce and hp <= 4:
        bid = max(bid, min(budget, 74.0))

    if bid < 0:
        bid = 0.0
    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no opponents, bid enough to secure water
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    # Read yesterday bids from immediate previous_trace
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Estimate competitive pressure
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # Typical aggressive range from trace: ~95-100; use it as anchor
        # If someone already bid very high, we must respond to avoid losing water.
        pressure = 1.0
        if highest_prev_bid >= DAILY_SALARY * 1.1:  # >= 88
            pressure = 1.25
        elif highest_prev_bid >= DAILY_SALARY * 0.8:  # >= 64
            pressure = 1.1
        else:
            pressure = 0.95
    else:
        highest_prev_bid = 0.0
        pressure = 1.0

    # Supply-to-water urgency: more supply means less aggressive needed
    # If supply is high, likely more water units exist; bid lower.
    # Use ratio to scale.
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    # Clamp
    if supply_ratio < 0.0:
        supply_ratio = 0.0
    if supply_ratio > 1.0:
        supply_ratio = 1.0

    # Base bid: moderate, slightly above typical aggressive bids when HP is low.
    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))

    # Target percentile: when HP is healthy, don't overpay.
    # When HP is critical, overpay to secure water.
    if hp >= 8:
        base = DAILY_SALARY * 0.45
    elif hp >= 4:
        base = DAILY_SALARY * 0.6
    else:
        base = DAILY_SALARY * 0.85

    # Adjust with pressure and supply
    # Higher supply -> bid less; lower supply -> bid more.
    supply_adjust = 1.0 + (0.12 * (1.0 - supply_ratio))

    # If yesterday highest bid was high, nudge upward to beat survival-chasers.
    # Otherwise keep near base.
    if highest_prev_bid > 0.0:
        # Aim to be competitive but not fully match the top bidder.
        top_nudge = 0.92 * highest_prev_bid
    else:
        top_nudge = 0.0

    bid = base * pressure * supply_adjust
    if top_nudge > 0.0:
        # Blend toward top_nudge
        bid = 0.65 * bid + 0.35 * top_nudge

    # Budget safety: never bid above what we can afford.
    if bid > budget:
        bid = budget

    # Also keep a minimum to avoid being outbid when HP is low.
    if hp < 4:
        min_bid = DAILY_SALARY * 0.55
        if bid < min_bid:
            bid = min(min_bid, budget)

    # If budget is very low, spend proportionally.
    if budget < DAILY_SALARY * 0.4:
        bid = min(budget, DAILY_SALARY * 0.7)

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)
